import type { Difficulty } from './difficulty';

/**
 * Missions (misiones, odd/tasks/achievements-missions.md): the town notice
 * board's job board in the style of the PMD rescue boards. Every number of
 * the board lives here; the missions themselves are generated by
 * core/missions.ts from the content lists (dungeons, challenges, species
 * lines, the dungeons' enemy types), so new content joins the board with
 * no edit here. Provisional numbers.
 */
export type MissionKind = 'floor' | 'clear' | 'defeat' | 'species';

export const MISSIONS = {
  /** Missions on the daily board (both inclusive). */
  dailyMin: 3,
  dailyMax: 5,
  /** Missions a player may hold at once (daily and weekly together). */
  maxAccepted: 3,
  /** Missions already claimed that the save remembers (today's and this week's only). */
  maxClaimed: 16,
  /** How often each kind of daily goal is drawn. */
  kindWeights: { floor: 3, clear: 3, defeat: 3, species: 2 } as Readonly<Record<MissionKind, number>>,
  /** The minimum tier of a daily mission; the weekly one draws from Normal up. */
  tierWeights: { easy: 4, normal: 4, hard: 2, nightmare: 1 } as Readonly<Record<Difficulty, number>>,
  /** Base Pokémonedas per goal kind (a defeat goal's grow with its count, per 10 enemies). */
  coins: { floor: 40, clear: 70, defeat: 40, species: 30 } as Readonly<Record<MissionKind, number>>,
  /** Pay multiplier by the mission's tier. */
  tierPay: { easy: 1, normal: 1.5, hard: 2, nightmare: 3 } as Readonly<Record<Difficulty, number>>,
  /** Enemies of a type a daily defeat goal asks for (both inclusive). */
  defeatCount: { min: 8, max: 20 },
  /** The Sima floor goals: multiples of `step`, up to `max`. */
  simaFloors: { step: 5, max: 20 },
  /** The weekly mission: its goal kinds, and its pay and defeat count against a daily one. */
  weekly: { kinds: ['clear', 'defeat'] as readonly MissionKind[], scale: 3 },
  /**
   * Evolution materials: a daily mission from Normal up pays them with this
   * chance (the weekly one always), `count` of them, of a tier at most the
   * mission's and never Pesadilla: the final evolution still needs a
   * Pesadilla clear of its challenge (data/player-evolutions.ts).
   */
  materials: { chance: 0.35, count: 1, weeklyCount: 2 },
} as const;
